#!/usr/bin/env bash

sudo apt-get -y update && sudo apt-get -y install cmake ninja-build libssl-dev libssh-dev libldap-dev libedit-dev
cmake -S. -Bcmake-build -GNinja -DPOCO_OSP_POCO_VERSION="${POCO_OSP_CI_POCO_VERSION}" \
	-DPOCO_OSP_MINIMAL_BUILD=ON -DPOCO_OSP_ENABLE_TESTS=ON -DPOCO_OSP_ENABLE_SAMPLES=ON \
	-DENABLE_OSP_BUNDLES=ON -DENABLE_OSP_BUNDLESIGN=ON -DENABLE_OSP_STRIPBUNDLE=ON -DENABLE_OSP_CODECACHE=ON \
	-DENABLE_OSP_CORE=ON -DENABLE_OSP_UNIT=ON \
	-DENABLE_OSP_NET=ON -DENABLE_OSP_NETSSL=ON -DENABLE_OSP_CRYPTO=ON -DENABLE_OSP_JWT=ON \
	-DENABLE_OSP_MAIL=ON -DENABLE_OSP_PROMETHEUS=ON -DENABLE_OSP_REDIS=ON \
	-DENABLE_OSP_WEB=ON -DENABLE_OSP_BUNDLEADMIN=ON -DENABLE_OSP_SIMPLEAUTH=ON \
	-DENABLE_OSP_AUTH=ON -DENABLE_OSP_AUTH_LDAP=ON \
	-DENABLE_OSP_DATA=ON -DENABLE_OSP_DATA_SQLITE=ON -DENABLE_OSP_ACTIVERECORD=ON \
	-DENABLE_OSP_SHELL=ON -DENABLE_OSP_SHELL_SSH=ON -DENABLE_OSP_SHELL_CLIENT=ON \
	-DENABLE_OSP_REMOTING=ON \
	&& cmake --build cmake-build --target all --parallel 4
